import{z as A,x as B,o as E,c as d,q as i,j as n,D as e,d as t,s,S as o,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"指令嵌入","description":"","frontmatter":{"title":"指令嵌入","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/instruction-embeddings.md","filePath":"llm/instruction-embeddings.md","lastUpdated":1791063341000}'),p={name:"llm/instruction-embeddings.md"};function m(h,a,u,C,D,T){const r=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=i('<h1 id="指令嵌入" tabindex="-1">指令嵌入 <a class="header-anchor" href="#指令嵌入" aria-label="Permalink to &quot;指令嵌入&quot;">​</a></h1><div class="epigraph"><p>同一句话，用作检索查询、用作要被检索的文档、用作聚类对象，需要的向量不同。把任务写成前缀指令，嵌入模型才知道该挤出哪一种语义。</p><footer>—— Su 等 INSTRUCTOR；后续 E5-Mistral / 指令式检索模型同一接口</footer></div><p><a href="/llm/matryoshka-embeddings">上一课</a>把维数当预算。还剩条件：双塔若永远用同一编码器无前缀，查询与文档、对称相似与非对称检索会互相伤害。本课写指令嵌入。缺口是任务条件化。后课多向量默认单向量已经按指令对齐，仍不够时再上晚交互。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「苹果」在新闻检索、产品搜索、聚类里应靠近不同的邻居。无指令的句向量只能学一个折中空间。Su 等人的 INSTRUCTOR 把自然语言指令拼在文本前，训练时覆盖检索、分类、聚类等任务，推理时改指令即改几何。查询侧指令（「把这个问题编成检索向量」）与文档侧指令（「把这段当成可检索段落」）可以不对称，这正是非对称检索需要的。</p><p><span class="marginnote">术语翻译：「任务条件化」就是给编码器一句口头说明——这次要为什么目的算向量。同一句「苹果发布会」，配上「为产品检索编码」会靠近手机词条，配上「为新闻主题聚类编码」会靠近科技事件。模型没换，换的是被指令拉出来的那块几何。</span></p><p>与生成式指令微调同构，但损失仍是对比，不是下一词。不要把 LLM 聊天模板原样套到嵌入模型上而不做对比训练。</p><p><span class="marginnote">指令是条件，不是第二个要交叉注意的句子。池化发生在「指令+文本」的整段双向表示上，见池化课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练数据要带任务指令，覆盖目标用例；指令多样性不足时，模型只学会几个模板。评测用 <a href="/llm/mteb">MTEB</a> 时，必须用该任务官方指令，否则与别人的分数不可比。部署：查询实时加指令，文档侧指令在建索引时写入——改指令等于重建索引。</p><p><span class="marginnote">数字实例：文档指令随向量存进索引，1 亿条文档、每条重嵌入按 1 毫秒算，换一次文档指令就是约 27.8 小时的纯计算，外加一遍存储重写；查询指令则每条请求实时拼上，零存量成本。所以「指令版本化」省的不是分数，是重算索引的钱。</span></p>',11)),(E(),n(o,null,{default:e(()=>[s(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INST%5B%22%E4%BB%BB%E5%8A%A1%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20ENC%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20ENC%0A%20%20ENC%20--%3E%20Z%5B%22%E6%9D%A1%E4%BB%B6%E5%8F%A5%E5%90%91%E9%87%8F%22%5D%0A%20%20Z%20--%3E%20TASK%5B%22%E6%A3%80%E7%B4%A2%20%2F%20%E8%81%9A%E7%B1%BB%20%2F%20%E5%88%86%E7%B1%BB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"指令 token 改变注意力下的汇聚：检索指令强调可匹配的关键约束，聚类指令强调主题，分类指令强调标签相关特征。对比损失把同一指令下的正对拉近。跨指令的几何不必连续——不要假设「改几个字指令」向量只小幅移动。因此指令要版本化，像聊天模板一样冻结。",-1)),(E(),n(o,null,{default:e(()=>[s(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20QI%5B%22%E6%9F%A5%E8%AF%A2%E6%8C%87%E4%BB%A4%EF%BC%9A%E7%BC%96%E6%88%90%E6%A3%80%E7%B4%A2%E5%90%91%E9%87%8F%22%5D%20--%3E%20QE%5B%22%E6%9F%A5%E8%AF%A2%E5%A1%94%22%5D%0A%20%20QT%5B%22%E7%94%A8%E6%88%B7%E9%97%AE%E9%A2%98%22%5D%20--%3E%20QE%0A%20%20DI%5B%22%E6%96%87%E6%A1%A3%E6%8C%87%E4%BB%A4%EF%BC%9A%E5%BD%93%E4%BD%9C%E5%8F%AF%E6%A3%80%E7%B4%A2%E6%AE%B5%E8%90%BD%22%5D%20--%3E%20DE%5B%22%E6%96%87%E6%A1%A3%E5%A1%94%22%5D%0A%20%20DT%5B%22%E5%80%99%E9%80%89%E6%AE%B5%E8%90%BD%22%5D%20--%3E%20DE%0A%20%20QE%20--%3E%20COS%5B%22%E4%BD%99%E5%BC%A6%E7%9B%B8%E4%BC%BC%E5%BA%A6%22%5D%0A%20%20DE%20--%3E%20COS%0A%20%20COS%20--%3E%20RANK%5B%22%E6%8C%89%E5%88%86%E6%95%B0%E6%8E%92%E5%BA%8F%E5%8F%AC%E5%9B%9E%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">常见误区：以为指令只是「多拼几个前缀 token」、向量八九不离十。实际上指令参与整段双向注意力与池化，会系统性搬动向量的位置；「检索」与「聚类」两条指令下同一句话的向量可以差很远，分数不在同一场比赛里。所以换了指令，就得重新校准阈值。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>指令不能替代相关性标注：再好的前缀也救不了假正例。超长指令会占掉文档有效长度。下一课多向量与晚交互：单向量条件化之后，仍需要 token 级交互的任务。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指令前缀让同一编码器服务多种度量任务，查询/文档可非对称。</li><li>改文档指令必须重建索引；评测锁官方指令。</li><li>损失仍是对比，不是聊天 SFT。</li><li>出处：Su 等 INSTRUCTOR；E5-Mistral 等指令检索模型。</li></ul>',5))])}const f=A(p,[["render",m]]);export{_ as __pageData,f as default};
